// Define a simple logging function (replace with a more robust logging system)
void logMessage(const std::string& message) {
    std::cout << "[" << __FILE__ << ":" << __LINE__ << "] " << message << std::endl;
}

// 1. Data Loading & Preprocessing
std::map<std::string, std::vector<std::string>> loadData(const std::string& dataDir) {
    std::map<std::string, std::vector<std::string>> data;
    for (const auto& filename : std::filesystem::directory_iterator(dataDir)) {
        std::string filename = filename.path().filename().string();
        if (filename.find(".csv") != std::string::npos) {
            // Load CSV data
            std::vector<std::string> csvData;
            std::ifstream file(filename);
            if (file.is_open()) {
                std::string line;
                while (std::getline(file, line)) {
                    csvData.push_back(line);
                }
                file.close();
                data[filename] = csvData;
            } else {
                logMessage("Error opening CSV file: " + filename);
            }
        } else if (filename.find(".json") != std::string::npos) {
            // Load JSON data
            std::ifstream file(filename);
            if (file.is_open()) {
                std::string jsonString;
                std::stringstream buffer;
                buffer << file.read(reinterpret_cast<char*>(jsonString.data()), jsonString.size());
                file.close();

                // Parse JSON string.
                auto json = nlohmann::json::parse(jsonString);

                // Convert json to vector of strings.
                std::vector<std::string> json_data;
                for (auto& entry : json) {
                    json_data.push_back(std::to_string(entry));
                }

                data[filename] = json_data;
            } else {
                logMessage("Error opening JSON file: " + filename);
            }
        }
    }
    return data;
}

