            chatFile.close();
        } else {
            logMessage("Error creating chat_logs.json");
        }
    }

    // Load data
    std::map<std::string, std::vector<std::string>> data = loadData(dataDirectory);

    // Analyze chat data
    std::map<std::string, double> chatAnalysis = analyzeChatData(data);

    // Analyze transaction data
    std::map<std::string, double> transactionAnalysis = analyzeTransactionData(data);

    // Generate report
    generateReport(chatAnalysis);
